lv_img_dsc_t icon_play;
lv_img_dsc_t icon_pause;
lv_img_dsc_t icon_prev;
lv_img_dsc_t icon_next;
lv_img_dsc_t icon_shuffle;
lv_img_dsc_t icon_repeat;

void iconsInit() {
  auto set = [](lv_img_dsc_t& d, const uint8_t* map) {
    memset(&d, 0, sizeof d);
    d.header.cf = LV_IMG_CF_ALPHA_8BIT;
    d.header.w = 32;
    d.header.h = 32;
    d.data_size = 1024;
    d.data = map;
  };
  set(icon_play, play_map);
  set(icon_pause, pause_map);
  set(icon_prev, prev_map);
  set(icon_next, next_map);
  set(icon_shuffle, shuffle_map);
  set(icon_repeat, repeat_map);
}
